  prevcased=0; ok=1; hascased=0;
  for(i=1;i<=length(w);i++){ c=substr(w,i,1);
    if(c ~ /[A-Z]/){ hascased=1; if(prevcased) ok=0; prevcased=1 }
    else if(c ~ /[a-z]/){ hascased=1; if(!prevcased) ok=0; prevcased=1 }
    else prevcased=0 }
