  prevcased=0; out="";
  for(i=1;i<=length(w);i++){ c=substr(w,i,1);
    if(c ~ /[a-zA-Z]/){ out = out (prevcased ? tolower(c) : toupper(c)); prevcased=1 }
    else { out=out c; prevcased=0 } }
  return out;
}
function pred(orig,  w,r){
  w=orig; gsub(/^[ \t]+|[ \t]+$/,"",w); w=tolower(w);
  if(w=="") return orig;
  r=core(w);
  if(orig ~ /[a-z]/ && orig !~ /[A-Z]/) return r;                 # islower
  if(orig ~ /[A-Z]/ && orig !~ /[a-z]/) return toupper(r);        # isupper
  if(istitle(orig)) return titlecase(r);
  return r;                                                      # fallback lower
}
{ e=pred($1); if(e!=$2) print "DEV\t[" $1 "]\tgot[" $2 "]\texp[" e "]" }
